on conflict (beer_name) do update set domains = excluded.domains, logo = excluded.logo;

on conflict (beer) do update set style = excluded.style, origin = excluded.origin, abv = excluded.abv, region = excluded.region, untappd = excluded.untappd, method = excluded.method, aka = excluded.aka, seq = excluded.seq;

on conflict (beer_name) do update set avg = excluded.avg;

on conflict (key) do update set value = excluded.value;
